#!/usr/bin/env python3
"""Preserve generated bytecode outside H2 source, 2026-11-13; known issue 3865.
Inputs: ignore-independent bytecode inventory and native lane launch timestamp.
Outputs: relocated bytecode and hash ledger in sibling scratch. A single-file
canary must pass before the rest can move. Never deletes or overwrites files.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
SCRATCH = ROOT.parent / 'scratch-h2-resume-20261113'
DEST = SCRATCH / 'source-bytecode'
LEDGER = SCRATCH / 'source-bytecode-ledger.json'


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def checkpoint(ledger):
    raw = (json.dumps(ledger, indent=2) + '\n').encode()
    with tempfile.NamedTemporaryFile(dir=SCRATCH, prefix='bytecode-ledger-update-', delete=False) as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())
        pending = Path(stream.name)
    os.replace(pending, LEDGER)
    descriptor = os.open(SCRATCH, os.O_RDONLY)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def verify(entry):
    target = Path(entry['destination'])
    assert target.is_file() and not target.is_symlink()
    assert target.stat().st_size == entry['bytes'] and digest(target) == entry['sha256']


def preserve(entry, ledger):
    source = ROOT / entry['former_relative_location']
    target = Path(entry['destination'])
    if target.exists():
        # Recover an interruption after rename but before its checkpoint.
        assert not source.exists(), 'Both locations exist; refuse an ambiguous recovery.'
        verify(entry)
    else:
        assert source.is_file() and not source.is_symlink()
        assert source.stat().st_size == entry['bytes'] and digest(source) == entry['sha256']
        target.parent.mkdir(parents=True, exist_ok=True)
        source.rename(target)
        assert not source.exists()
        verify(entry)
    entry['state'] = 'preserved'
    checkpoint(ledger)


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('phase', choices=('canary', 'remaining'))
    args = p.parse_args()
    lower = (SCRATCH / 'native/command.json').stat().st_mtime_ns
    command = ['rg', '--files', '--hidden', '--no-ignore', 'src', 'notes', 'tests', 'scripts',
               '-g', '*.pyc', '-g', '*.pyo']
    scan = subprocess.run(command, cwd=ROOT, text=True, capture_output=True)
    assert scan.returncode in (0, 1), scan.stderr
    candidates = []
    retained_older = []
    for relative in sorted(scan.stdout.splitlines()):
        path = ROOT / relative
        assert path.is_file() and not path.is_symlink()
        if path.stat().st_mtime_ns < lower:
            retained_older.append(relative)
            continue
        candidates.append(path)
    if not LEDGER.exists():
        assert args.phase == 'canary' and candidates
        ledger = {'known_issue': 3865, 'scan_command': command, 'status': 'planned',
                  'mtime_threshold_ns': lower,
                  'selection': 'Bytecode mtime is at or after the recorded native lane command; no origin is inferred for older files.',
                  'workflow': str(ROOT / '.github/workflows/main.yaml'),
                  'entries': [], 'older_files_retained': retained_older}
        for path in candidates:
            relative = path.relative_to(ROOT)
            ledger['entries'].append({'state': 'planned', 'former_relative_location': str(relative),
                'destination': str(DEST / relative), 'bytes': path.stat().st_size,
                'mtime_ns': path.stat().st_mtime_ns, 'sha256': digest(path)})
        ledger['canary'] = ledger['entries'][0]['former_relative_location']
        checkpoint(ledger)  # Complete inventory is durable before any move.
    else:
        ledger = json.loads(LEDGER.read_bytes())
        assert ledger['mtime_threshold_ns'] == lower
    if args.phase == 'canary':
        assert ledger['status'] in ('planned', 'canary_verified')
        selected = ledger['entries'][:1]
    else:
        assert ledger['status'] in ('canary_verified', 'complete')
        prior = ledger['entries'][0]
        assert prior['state'] == 'preserved'
        verify(prior)
        selected = ledger['entries'][1:]
    planned = {entry['former_relative_location'] for entry in ledger['entries']}
    assert all(str(path.relative_to(ROOT)) in planned for path in candidates), 'New bytecode needs a fresh reviewed inventory.'
    for entry in selected:
        preserve(entry, ledger)
    ledger['status'] = 'canary_verified' if args.phase == 'canary' else 'complete'
    if args.phase == 'remaining':
        for entry in ledger['entries']:
            assert entry['state'] == 'preserved'
            verify(entry)
            assert not (ROOT / entry['former_relative_location']).exists()
    checkpoint(ledger)
    print(json.dumps({'path': str(LEDGER), 'sha256': digest(LEDGER), 'status': ledger['status'],
                      'verified_this_phase': len(selected),
                      'total_preserved': sum(entry['state'] == 'preserved' for entry in ledger['entries'])}))


if __name__ == '__main__':
    main()
